DELETE FROM "PurchaseOrder";
DELETE FROM "MedicineBatch";
DELETE FROM "Medicine";
DELETE FROM "Expense";
DELETE FROM "Staff";
DELETE FROM "Dealer";
DELETE FROM "User";
